import threading
import queue
import numpy as np

import time

class Fsm(threading.Thread):
    def __init__(self, update_callback):
        super(Fsm, self).__init__(daemon=True)

        self.__running = threading.Event() # ID used to stop the thread
        self.__resume = threading.Event() # ID used to pause the thread
        
        self.update_callback = update_callback

        # Queues for simulation values
        self.q_x = queue.Queue()
        self.q_P = queue.Queue()


    def start(self):
        self.__resume.set()
        self.__running.set()
        if not self.is_alive():
            super().start()

    def pause(self):
        self.__resume.clear()

    def resume(self):
        self.__resume.set()

    def stop(self):
        self.__resume.set()
        self.__running.clear()

